def confusion(aktual, prediksi, positif="ya"):
    hasil = {"TP": 0, "TN": 0, "FP": 0, "FN": 0}
    for a, p in zip(aktual, prediksi):
        if a == positif and p == positif:
            hasil["TP"] += 1
        elif a == positif:
            hasil["FN"] += 1
        elif p == positif:
            hasil["FP"] += 1
        else:
            hasil["TN"] += 1
    return hasil


print(confusion(AKTUAL, PREDIKSI))

def f1(aktual, prediksi, positif="ya"):
    c = confusion(aktual, prediksi, positif)
    tp, fp, fn = c["TP"], c["FP"], c["FN"]
    precision = tp / (tp + fp) if tp + fp else 0
    recall = tp / (tp + fn) if tp + fn else 0
    if precision + recall == 0:
        return 0
    return 2 * precision * recall / (precision + recall)


print(f1(AKTUAL, PREDIKSI))

