def cek_bias(data, kolom):
    jumlah, positif = {}, {}
    for r in data:
        g = r[kolom]
        jumlah[g] = jumlah.get(g, 0) + 1
        positif[g] = positif.get(g, 0) + r["diterima"]
    return {g: round(positif[g] / jumlah[g], 2) for g in jumlah}


def rasio_dampak(proporsi):
    terbesar = max(proporsi.values())
    if terbesar == 0:
        return 0.0
    return round(min(proporsi.values()) / terbesar, 2)


print(cek_bias(PENDAFTAR, "wilayah"))
